package dev.cipherkeep.app.data.db

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase
import net.zetetic.database.sqlcipher.SupportOpenHelperFactory
import java.io.File

/**
 * SQLCipher-backed vault database.
 *
 * The passphrase is generated by [dev.cipherkeep.app.data.keystore.PassphraseStore]
 * and is never persisted in plaintext. The database file lives in the app's
 * private database directory and is excluded from backup by the manifest rules.
 */
@Database(
    entities = [ItemEntity::class],
    version = VaultDatabase.VERSION,
    exportSchema = true,
)
abstract class VaultDatabase : RoomDatabase() {
    abstract fun itemDao(): ItemDao

    companion object {
        const val VERSION = 3
        const val NAME = "vault.db"

        /** Adds the sticky-deletion flag introduced by schema v2. */
        val MIGRATION_1_2 = object : Migration(1, 2) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("ALTER TABLE items ADD COLUMN tombstone INTEGER NOT NULL DEFAULT 0")
            }
        }

        /** Adds the canonical V2 sync record column. */
        val MIGRATION_2_3 = object : Migration(2, 3) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("ALTER TABLE items ADD COLUMN sync_record BLOB")
            }
        }

        /**
         * Open the encrypted database. Callers must clear [passphrase] after
         * this function returns.
         */
        fun open(context: Context, passphrase: ByteArray): VaultDatabase {
            require(passphrase.size == 32) { "database passphrase must be 32 bytes" }
            System.loadLibrary("sqlcipher")
            val factory = SupportOpenHelperFactory(passphrase)
            return Room.databaseBuilder(context, VaultDatabase::class.java, NAME)
                .openHelperFactory(factory)
                .addMigrations(MIGRATION_1_2, MIGRATION_2_3)
                .setJournalMode(JournalMode.WRITE_AHEAD_LOGGING)
                .addCallback(
                    object : Callback() {
                        override fun onOpen(db: SupportSQLiteDatabase) {
                            db.execSQL("PRAGMA cipher_memory_security = ON")
                            db.execSQL("PRAGMA foreign_keys = ON")
                        }
                    },
                )
                .build()
        }

        fun deleteFiles(context: Context) {
            context.deleteDatabase(NAME)
            File(context.getDatabasePath(NAME).parentFile, "$NAME-wal").delete()
            File(context.getDatabasePath(NAME).parentFile, "$NAME-shm").delete()
        }
    }
}
